package com.northstarbank.console.web;import com.northstarbank.console.integration.TierClient;import com.northstarbank.console.security.AuthorizationService;import com.northstarbank.console.service.AuditService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@Controller @RequestMapping("/admin/staff") public class AdminController{private final AuthorizationService auth;private final TierClient tiers;private final AuditService audit;public AdminController(AuthorizationService a,TierClient t,AuditService l){auth=a;tiers=t;audit=l;}@GetMapping String list(Model m){auth.require("ADMIN_STAFF",null,false);m.addAttribute("staff",tiers.staff(auth.user().token()));m.addAttribute("delegations",tiers.delegations(auth.user().token()));m.addAttribute("form",new StaffForm("","","CSR","B01","R1",""));return"admin-staff";}@PostMapping String create(@Valid @ModelAttribute("form")StaffForm f,BindingResult errors,Model m){auth.require("ADMIN_STAFF",null,false);if(errors.hasErrors()){m.addAttribute("staff",tiers.staff(auth.user().token()));m.addAttribute("delegations",tiers.delegations(auth.user().token()));return"admin-staff";}tiers.createStaff(auth.user().token(),new TierClient.StaffCreate(f.employeeId(),f.email(),f.role(),f.homeBranch(),f.region(),f.temporaryPassword()));audit.record("STAFF_CREATED","staff",1,null,"security_admin",null,f.employeeId());return"redirect:/admin/staff?created";}@PostMapping("/{id}/enabled")String enabled(@PathVariable String id,@RequestParam boolean value){auth.require("ADMIN_STAFF",null,false);tiers.setEnabled(auth.user().token(),id,value);audit.record(value?"STAFF_ENABLED":"STAFF_DISABLED","staff",1,null,"security_admin",null,id);return"redirect:/admin/staff";}@PostMapping("/delegations")String delegation(@RequestParam String delegatorId,@RequestParam String delegateId,@RequestParam String grantedScope,@RequestParam java.math.BigDecimal grantedLimit,@RequestParam java.time.LocalDate startDate,@RequestParam java.time.LocalDate endDate){auth.require("ADMIN_STAFF",null,false);tiers.createDelegation(auth.user().token(),new TierClient.DelegationCreate(delegatorId,delegateId,grantedScope,grantedLimit,startDate,endDate));audit.record("DELEGATION_CREATED","delegation",1,null,"security_admin",null,delegatorId+"->"+delegateId);return"redirect:/admin/staff?delegated";}@PostMapping("/delegations/{id}/revoke")String revoke(@PathVariable long id){auth.require("ADMIN_STAFF",null,false);tiers.revokeDelegation(auth.user().token(),id);audit.record("DELEGATION_REVOKED","delegation",1,null,"security_admin",null,String.valueOf(id));return"redirect:/admin/staff";}@PostMapping("/import")String roster(@RequestParam MultipartFile file)throws IOException{auth.require("ADMIN_STAFF",null,false);if(file.isEmpty()||file.getSize()>1_000_000)throw new IllegalArgumentException("Invalid roster");int count=0;try(var reader=new BufferedReader(new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8))){String line;reader.readLine();while((line=reader.readLine())!=null){String[] c=line.split(",",-1);if(c.length!=5)continue;tiers.createStaff(auth.user().token(),new TierClient.StaffCreate(c[0].trim(),c[1].trim(),c[2].trim(),c[3].trim(),c[4].trim(),"Temporary123!"));count++;}}audit.record("STAFF_ROSTER_IMPORTED","staff",count,null,"security_admin",null,"rows="+count);return"redirect:/admin/staff?imported="+count;}public record StaffForm(@Pattern(regexp="EMP\\d{3,6}")String employeeId,@Email String email,@Pattern(regexp="CSR|BRANCH_OFFICER|BRANCH_SUPERVISOR|REGIONAL_MANAGER|HEAD_OFFICE_OPS|SECURITY_ADMIN")String role,@Pattern(regexp="B0[1-9]")String homeBranch,@Pattern(regexp="R[1-3]")String region,@Size(min=12,max=80)String temporaryPassword){}}
